const PlaygroundSource = "import {
  DatePicker,
  DatePickerCalendar,
  DatePickerContent,
  DatePickerInput,
} from "@/registry/erbium/ui/date-picker";

const Example = (args: {
  mode: "single" | "range";
  disabled: boolean;
  closeOnSelect: boolean;
  numberOfMonths: number;
  captionLayout: "label" | "dropdown";
}) => (
  <DatePicker
    // Remount when the mode changes so each mode starts from an empty value.
    key={args.mode}
